CREATE TABLE IF NOT EXISTS rel_aggregates (parent_guid TEXT NOT NULL, child_guid TEXT NOT NULL, PRIMARY KEY (parent_guid, child_guid));
-- §NOGEO_COMPOSE (2026-08-10): real IfcRelAggregates parent->child pairs for Clinic's 43
-- guid-only elements (31 IfcCurtainWall + 7 IfcRoof + 4 IfcStair + 1 IfcRamp authored with no own
-- Representation -- their geometry lives entirely on these children). Same class as the
-- Hospital/Duplex/HHS_Office_Federated gap; Clinic was NOT in that lane's "3 known-affected
-- buildings" list -- found by sweeping the ghost-count query over every shipped DB, and confirmed
-- against the LIVE OCI bytes (buildings/Clinic_meta.db, 43 ghosts), not just a local copy.
-- Extracted literally from the source IFCs: internal/UNMERGED/Clinic_Architectural_IFC2x3.ifc
-- (726 pairs) + Clinic_Structural_IFC2x3.ifc (12); Electrical/HVAC/Plumbing contributed none.
-- No computed values here -- the union-bbox composition runs client-side at load time
-- (viewer/scene.js composeGhostsFromAggregates). 738 pairs / 43 parents, all 43 resolvable.
-- Witness: W-NOGEO-COMPOSE (tests/witness_nogeo_compose.js).
-- See prompts/4D_SCHEDULE_PERFECTION.md §NOGEO_COMPOSE push-to-zero.
